"""Generate the agent files and the reference skill from config and policy text."""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Optional

sys.dont_write_bytecode = True

from policy_text import SECTIONS_DIR, base_values, render  # noqa: E402
from routing_config import (  # noqa: E402
    CONFIG_PATH,
    REPO_ROOT,
    ConfigError,
    RoutingConfig,
    Tier,
    load_config,
)

TEMPLATES_DIR = REPO_ROOT / "policy" / "agents"
GENERATED_NOTE = (
    "<!-- Generated by scripts/generate.py from config/routing.json and policy/; "
    "edit those and regenerate. -->"
)
REFERENCE_DESCRIPTION = (
    "Full text of the Model Routing Policy: lanes, the full-lane workflow and gate, tier "
    "selection, the Plan Contract, verification triggers, calibration sampling, logging and "
    "limits. Use when you need the exact wording of a routing rule."
)
EXTRA_RULES_PLACEHOLDER = "{{extra_rules}}"
SKILL_RELPATH = Path("skills") / "routing-policy" / "SKILL.md"


def tier_values(config: RoutingConfig, tier: Tier) -> dict:
    values = base_values(config)
    values["tier_name"] = tier.name
    cap_key = "skill_cap_haiku" if tier.family == "haiku" else "skill_cap_other"
    values["skill_cap"] = values[cap_key]
    rules = config.extra_rules_by_model.get(tier.family, ())
    values["extra_rules"] = "\n".join("- " + rule for rule in rules)
    return values


def _frontmatter(pairs: list) -> str:
    return "\n".join(["---"] + [f"{key}: {value}" for key, value in pairs] + ["---"]) + "\n"


def _format_value(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def render_frontmatter(config: RoutingConfig, tier: Tier) -> str:
    role = config.roles[tier.role]
    extra = list(config.agent_frontmatter)
    extra += list(config.agent_frontmatter_by_model.get(tier.family, ()))
    return _frontmatter([
        ("name", tier.name),
        ("description", json.dumps(tier.description, ensure_ascii=False)),
        ("model", tier.model),
        ("effort", tier.effort),
        ("tools", ", ".join(role.tools)),
        ("disallowedTools", ", ".join(role.disallowed_tools)),
    ] + [(key, _format_value(value)) for key, value in extra])


def render_agent(
    config: RoutingConfig, tier: Tier, templates_dir: Path = TEMPLATES_DIR,
    sections_dir: Path = SECTIONS_DIR,
) -> str:
    template = (templates_dir / f"{tier.role}.md").read_text(encoding="utf-8")
    values = tier_values(config, tier)
    if not values["extra_rules"]:
        kept = [ln for ln in template.split("\n") if ln.strip() != EXTRA_RULES_PLACEHOLDER]
        template = "\n".join(kept)
    body = render(template, values, sections_dir).strip()
    return render_frontmatter(config, tier) + "\n" + GENERATED_NOTE + "\n\n" + body + "\n"


def render_reference_skill(config: RoutingConfig, sections_dir: Path = SECTIONS_DIR) -> str:
    values = base_values(config)
    head = _frontmatter([
        ("name", "routing-policy"),
        ("description", json.dumps(REFERENCE_DESCRIPTION)),
    ])
    intro = (
        "\n" + GENERATED_NOTE + "\n\n# Model Routing Policy\n\n"
        "Policy revision 2.1, as shipped by the {{plugin_name}} plugin. "
        "Tier names are short names; dispatch them as `{{plugin_name}}:<name>`.\n\n"
    )
    sections = [
        render(f"{{{{section:{name}}}}}", values, sections_dir).rstrip()
        for name in config.policy_sections
    ]
    return head + render(intro, values, sections_dir) + "\n\n".join(sections) + "\n"


def expected_outputs(
    config: RoutingConfig, root: Path, templates_dir: Optional[Path] = None,
    sections_dir: Optional[Path] = None,
) -> dict:
    templates = templates_dir or TEMPLATES_DIR
    sections = sections_dir or SECTIONS_DIR
    outputs = {
        root / "agents" / f"{tier.name}.md": render_agent(config, tier, templates, sections)
        for tier in config.tiers
    }
    outputs[root / SKILL_RELPATH] = render_reference_skill(config, sections)
    return outputs


def write_outputs(outputs: dict) -> None:
    for path, text in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")


def check_outputs(outputs: dict, root: Path) -> list:
    problems = []
    for path, text in sorted(outputs.items()):
        if not path.is_file():
            problems.append(f"missing: {path}")
        elif path.read_text(encoding="utf-8") != text:
            problems.append(f"stale: {path}")
    agents_dir = root / "agents"
    if agents_dir.is_dir():
        problems += [
            f"unexpected: {p}" for p in sorted(agents_dir.glob("*.md")) if p not in outputs
        ]
    return problems


def main(argv: Optional[list] = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="report stale outputs, write nothing")
    parser.add_argument("--root", default=str(REPO_ROOT), help="directory to write outputs to")
    args = parser.parse_args(argv)
    root = Path(args.root)
    try:
        outputs = expected_outputs(load_config(CONFIG_PATH), root)
    except (ConfigError, ValueError) as exc:
        print(f"generate: {exc}", file=sys.stderr)
        return 2
    if not args.check:
        write_outputs(outputs)
        return 0
    problems = check_outputs(outputs, root)
    for problem in problems:
        print(problem)
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
